import { Tool } from '@n8n/agents';
import { z } from 'zod';

export default new Tool('fetch_klir_skill')
  .description('Fetch a Klir IA skill playbook from https://klirline.io/api/skills/{name}')
  .input(z.object({ name: z.string().describe('Skill name e.g. copywriting, social, seo-audit') }))
  .handler(async ({ name }) => {
    const base = process.env.KLIR_IA_API_URL ?? 'https://klirline.io';
    const res = await fetch(`${base}/api/skills/${encodeURIComponent(name)}`);
    if (!res.ok) return { error: `Skill not found: ${name}`, status: res.status };
    const data = await res.json();
    return { name: data.name, description: data.description, body: data.body?.slice(0, 8000) };
  });
